window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b296fe80ae396e5c"]={"versions": [{"id": "FIG-b296fe80ae396e5c", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (<em>Activity Diagram</em>) mit Kontrollfluss, Verzweigung/Zusammenführung (<em>Decision/Merge Nodes</em>) und annotierter Berechnungs-Note.</li>\n<li><strong>Architektur-Kontext:</strong> Teil der AUTOSAR E2E Library (<code>E2E Protocol</code>, Profil 11). Das Diagramm spezifiziert den Teilschritt <em>„Read DataIDNibble“</em> innerhalb der Verifikationsfunktion <code>E2E_P11Check()</code>.</li>\n<li><strong>Funktionale Einordnung:</strong> Dient der sicherheitsrelevanten Integritätsprüfung empfangener Nutzdaten (Safety Communication gem. ISO 26262). Wenn Profil 11 im Modus <code>E2E_P11_DATAID_NIBBLE</code> betrieben wird, überträgt der Sender ein 4-Bit-Nibble der Data-ID explizit im Datenstrom, um Aliasing-Effekte bei Masquerading-Fehlern zu minimieren.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aufrufkontext:</strong> Funktion <code>E2E_P11Check(const E2E_P11ConfigType<em> Config, E2E_P11CheckStateType</em> State, const uint8* Data, uint16 Length)</code>.</li>\n<li><strong>Verwendete Konfigurationsparameter & Datenstrukturen (<code>Config</code>):</strong></li>\n<li><code>Config-&gt;DataIDMode</code>: Enum zur Steuerung des Data-ID-Übertragungsverfahrens (u. a. <code>E2E_P11_DATAID_NIBBLE</code>, <code>E2E_P11_DATAID_BOTH</code>, etc.).</li>\n<li><code>Config-&gt;NibbleOffset</code>: Bit-Offset (<code>uint16</code>) des zu lesenden Data-ID-Nibbles innerhalb des serialisierten Byte-Arrays <code>Data</code>.</li>\n<li><strong>Eingangsdaten:</strong></li>\n<li><code>Data</code>: Zeiger auf das empfangene Nutzdaten-Array (<code>const uint8*</code>).</li>\n<li><strong>Lokale Variablen:</strong></li>\n<li><code>ReceivedNibble</code>: Temporäre 8-Bit-Variable (<code>uint8</code>) zur Aufnahme des extrahierten 4-Bit-Werts (Bits [3:0]).</li>\n<li><code>Byte</code>: Temporäre Variable zum Zugriff auf das adressierte Byte im PDU-Puffer.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer Eintritt:</strong> Start des Sub-Schritts aus dem Hauptablauf von <code>E2E_P11Check()</code>.</li>\n<li>*<em>Evaluierung der Bedingung (</em>Decision Node<em>):</em>*</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung: <code>Config-&gt;DataIDMode == E2E_P11_DATAID_NIBBLE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zweig [TRUE] – Nibble-Extraktion:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ermittlung des Byte-Index im Array über Bitshift:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{Byte} = \\text{Data}[\\text{Config}\\rightarrow\\text{NibbleOffset} \\gg 3]$$</p>\n<ul class=\"fig-list\">\n<li>Extraktion des 4-Bit-Nibbles (Little-Endian-Bitordnung, LSB-first-Ausrichtung) und Zuweisung an <code>ReceivedNibble</code>:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{ReceivedNibble} = (\\text{Byte} \\gg (\\text{Config}\\rightarrow\\text{NibbleOffset} \\ \\& \\ 0\\text{x}7)) \\ \\& \\ 0\\text{x}F$$</p>\n<ul class=\"fig-list\">\n<li>Weiterleitung zum Merge-Knoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zweig [FALSE] – Bypass:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wenn ein anderer Data-ID-Modus konfiguriert ist, wird kein Nibble aus den Nutzdaten gelesen.</li>\n<li>Direkter Sprung auf den Merge-Knoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss:</strong> Zusammenführung im <em>Merge Node</em> und Übergang zum nachfolgenden Schritt der Prüflogik (Validierung des CRC bzw. Vergleich des DataIDNibbles mit der erwarteten Data-ID).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Zuordnung:</strong> Erfüllt die Anforderungen [PRS_E2E_00582] (Verhalten des Leseschritts) und [PRS_E2E_00517] i. V. m. [RS_E2E_08539].</li>\n<li><strong>Bit-Alignment & Endianness:</strong></li>\n<li>Der Bit-Offset (<code>NibbleOffset</code>) bezieht sich strikt auf Little-Endian-Bit-Nummerierung (Bit 0 = niederwertigstes Bit im Byte).</li>\n<li><code>NibbleOffset</code> muss zwingend auf eine Nibble-Grenze ausgerichtet sein (Bit-Position modulo 4 == 0). Ein Nibble darf gemäß Spezifikation nicht über Byte-Grenzen hinweg fragmentiert werden.</li>\n<li><strong>Implementierungsfalle im Spezifikations-Kommentar:</strong></li>\n<li>Der Text der informativen Note im Diagramm verwendet irrtümlich den Variablennamen <code>Counter = ...</code> (Textübertrag aus dem Zähler-Extraktionsschritt). Für die Implementierung ist dieser Wert semantisch exakt als <code>ReceivedNibble</code> zu führen.</li>\n<li><strong>Effizienz / Optimierung:</strong></li>\n<li>Da <code>NibbleOffset &amp; 0x7</code> entweder <code>0</code> (unteres Nibble) oder <code>4</code> (oberes Nibble) ergibt, lässt sich der Shift-Ausdruck auf 8-Bit-Microcontrollern compilerseitig oder per Makro auf eine einfache Verzweigung oder Fest-Shift-Operation optimieren:</li>\n<li>Offset im Byte = 0: <code>Data[...] &amp; 0x0F</code></li>\n<li>Offset im Byte = 4: <code>(Data[...] &gt;&gt; 4) &amp; 0x0F</code></li>\n<li><strong>Defensive Robustheit:</strong> <code>Data</code> muss vor Betreten dieses Schritts validiert sein (<code>Data != NULL</code> und PDU-Länge deckt <code>(NibbleOffset + 4)</code> ab), um Out-of-Bounds-Lesezugriffe zu verhindern.</li>\n</ul>"}, {"id": "FIG-094a54c7051d0605", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (<em>Activity Diagram</em>) mit Kontrollfluss, Verzweigung/Zusammenführung (<em>Decision/Merge Nodes</em>) und annotierter Berechnungs-Note.</li>\n<li><strong>Architektur-Kontext:</strong> Teil der AUTOSAR E2E Library (<code>E2E Protocol</code>, Profil 11). Das Diagramm spezifiziert den Teilschritt <em>„Read DataIDNibble“</em> innerhalb der Verifikationsfunktion <code>E2E_P11Check()</code>.</li>\n<li><strong>Funktionale Einordnung:</strong> Dient der sicherheitsrelevanten Integritätsprüfung empfangener Nutzdaten (Safety Communication gem. ISO 26262). Wenn Profil 11 im Modus <code>E2E_P11_DATAID_NIBBLE</code> betrieben wird, überträgt der Sender ein 4-Bit-Nibble der Data-ID explizit im Datenstrom, um Aliasing-Effekte bei Masquerading-Fehlern zu minimieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aufrufkontext:</strong> Funktion <code>E2E_P11Check(const E2E_P11ConfigType<em> Config, E2E_P11CheckStateType</em> State, const uint8* Data, uint16 Length)</code>.</li>\n<li><strong>Verwendete Konfigurationsparameter & Datenstrukturen (<code>Config</code>):</strong></li>\n<li><code>Config-&gt;DataIDMode</code>: Enum zur Steuerung des Data-ID-Übertragungsverfahrens (u. a. <code>E2E_P11_DATAID_NIBBLE</code>, <code>E2E_P11_DATAID_BOTH</code>, etc.).</li>\n<li><code>Config-&gt;NibbleOffset</code>: Bit-Offset (<code>uint16</code>) des zu lesenden Data-ID-Nibbles innerhalb des serialisierten Byte-Arrays <code>Data</code>.</li>\n<li><strong>Eingangsdaten:</strong></li>\n<li><code>Data</code>: Zeiger auf das empfangene Nutzdaten-Array (<code>const uint8*</code>).</li>\n<li><strong>Lokale Variablen:</strong></li>\n<li><code>ReceivedNibble</code>: Temporäre 8-Bit-Variable (<code>uint8</code>) zur Aufnahme des extrahierten 4-Bit-Werts (Bits [3:0]).</li>\n<li><code>Byte</code>: Temporäre Variable zum Zugriff auf das adressierte Byte im PDU-Puffer.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer Eintritt:</strong> Start des Sub-Schritts aus dem Hauptablauf von <code>E2E_P11Check()</code>.</li>\n<li>*<em>Evaluierung der Bedingung (</em>Decision Node<em>):</em>*</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung: <code>Config-&gt;DataIDMode == E2E_P11_DATAID_NIBBLE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zweig [TRUE] – Nibble-Extraktion:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ermittlung des Byte-Index im Array über Bitshift:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{Byte} = \\text{Data}[\\text{Config}\\rightarrow\\text{NibbleOffset} \\gg 3]$$</p>\n<ul class=\"fig-list\">\n<li>Extraktion des 4-Bit-Nibbles (Little-Endian-Bitordnung, LSB-first-Ausrichtung) und Zuweisung an <code>ReceivedNibble</code>:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{ReceivedNibble} = (\\text{Byte} \\gg (\\text{Config}\\rightarrow\\text{NibbleOffset} \\ \\& \\ 0\\text{x}7)) \\ \\& \\ 0\\text{x}F$$</p>\n<ul class=\"fig-list\">\n<li>Weiterleitung zum Merge-Knoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zweig [FALSE] – Bypass:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wenn ein anderer Data-ID-Modus konfiguriert ist, wird kein Nibble aus den Nutzdaten gelesen.</li>\n<li>Direkter Sprung auf den Merge-Knoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss:</strong> Zusammenführung im <em>Merge Node</em> und Übergang zum nachfolgenden Schritt der Prüflogik (Validierung des CRC bzw. Vergleich des DataIDNibbles mit der erwarteten Data-ID).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Zuordnung:</strong> Erfüllt die Anforderungen [PRS_E2E_00582] (Verhalten des Leseschritts) und [PRS_E2E_00517] i. V. m. [RS_E2E_08539].</li>\n<li><strong>Bit-Alignment & Endianness:</strong></li>\n<li>Der Bit-Offset (<code>NibbleOffset</code>) bezieht sich strikt auf Little-Endian-Bit-Nummerierung (Bit 0 = niederwertigstes Bit im Byte).</li>\n<li><code>NibbleOffset</code> muss zwingend auf eine Nibble-Grenze ausgerichtet sein (Bit-Position modulo 4 == 0). Ein Nibble darf gemäß Spezifikation nicht über Byte-Grenzen hinweg fragmentiert werden.</li>\n<li><strong>Implementierungsfalle im Spezifikations-Kommentar:</strong></li>\n<li>Der Text der informativen Note im Diagramm verwendet irrtümlich den Variablennamen <code>Counter = ...</code> (Textübertrag aus dem Zähler-Extraktionsschritt). Für die Implementierung ist dieser Wert semantisch exakt als <code>ReceivedNibble</code> zu führen.</li>\n<li><strong>Effizienz / Optimierung:</strong></li>\n<li>Da <code>NibbleOffset &amp; 0x7</code> entweder <code>0</code> (unteres Nibble) oder <code>4</code> (oberes Nibble) ergibt, lässt sich der Shift-Ausdruck auf 8-Bit-Microcontrollern compilerseitig oder per Makro auf eine einfache Verzweigung oder Fest-Shift-Operation optimieren:</li>\n<li>Offset im Byte = 0: <code>Data[...] &amp; 0x0F</code></li>\n<li>Offset im Byte = 4: <code>(Data[...] &gt;&gt; 4) &amp; 0x0F</code></li>\n<li><strong>Defensive Robustheit:</strong> <code>Data</code> muss vor Betreten dieses Schritts validiert sein (<code>Data != NULL</code> und PDU-Länge deckt <code>(NibbleOffset + 4)</code> ab), um Out-of-Bounds-Lesezugriffe zu verhindern.</li>\n</ul>"}, {"id": "FIG-3395dac47b8835d5", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Aktivitätsdiagramm (<em>Activity Diagram</em>) mit Kontrollfluss, Verzweigung/Zusammenführung (<em>Decision/Merge Nodes</em>) und annotierter Berechnungs-Note.</li>\n<li><strong>Architektur-Kontext:</strong> Teil der AUTOSAR E2E Library (<code>E2E Protocol</code>, Profil 11). Das Diagramm spezifiziert den Teilschritt <em>„Read DataIDNibble“</em> innerhalb der Verifikationsfunktion <code>E2E_P11Check()</code>.</li>\n<li><strong>Funktionale Einordnung:</strong> Dient der sicherheitsrelevanten Integritätsprüfung empfangener Nutzdaten (Safety Communication gem. ISO 26262). Wenn Profil 11 im Modus <code>E2E_P11_DATAID_NIBBLE</code> betrieben wird, überträgt der Sender ein 4-Bit-Nibble der Data-ID explizit im Datenstrom, um Aliasing-Effekte bei Masquerading-Fehlern zu minimieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aufrufkontext:</strong> Funktion <code>E2E_P11Check(const E2E_P11ConfigType<em> Config, E2E_P11CheckStateType</em> State, const uint8* Data, uint16 Length)</code>.</li>\n<li><strong>Verwendete Konfigurationsparameter & Datenstrukturen (<code>Config</code>):</strong></li>\n<li><code>Config-&gt;DataIDMode</code>: Enum zur Steuerung des Data-ID-Übertragungsverfahrens (u. a. <code>E2E_P11_DATAID_NIBBLE</code>, <code>E2E_P11_DATAID_BOTH</code>, etc.).</li>\n<li><code>Config-&gt;NibbleOffset</code>: Bit-Offset (<code>uint16</code>) des zu lesenden Data-ID-Nibbles innerhalb des serialisierten Byte-Arrays <code>Data</code>.</li>\n<li><strong>Eingangsdaten:</strong></li>\n<li><code>Data</code>: Zeiger auf das empfangene Nutzdaten-Array (<code>const uint8*</code>).</li>\n<li><strong>Lokale Variablen:</strong></li>\n<li><code>ReceivedNibble</code>: Temporäre 8-Bit-Variable (<code>uint8</code>) zur Aufnahme des extrahierten 4-Bit-Werts (Bits [3:0]).</li>\n<li><code>Byte</code>: Temporäre Variable zum Zugriff auf das adressierte Byte im PDU-Puffer.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialer Eintritt:</strong> Start des Sub-Schritts aus dem Hauptablauf von <code>E2E_P11Check()</code>.</li>\n<li>*<em>Evaluierung der Bedingung (</em>Decision Node<em>):</em>*</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Prüfung: <code>Config-&gt;DataIDMode == E2E_P11_DATAID_NIBBLE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zweig [TRUE] – Nibble-Extraktion:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ermittlung des Byte-Index im Array über Bitshift:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{Byte} = \\text{Data}[\\text{Config}\\rightarrow\\text{NibbleOffset} \\gg 3]$$</p>\n<ul class=\"fig-list\">\n<li>Extraktion des 4-Bit-Nibbles (Little-Endian-Bitordnung, LSB-first-Ausrichtung) und Zuweisung an <code>ReceivedNibble</code>:</li>\n</ul>\n<p class=\"fig-p\">$$\\text{ReceivedNibble} = (\\text{Byte} \\gg (\\text{Config}\\rightarrow\\text{NibbleOffset} \\ \\& \\ 0\\text{x}7)) \\ \\& \\ 0\\text{x}F$$</p>\n<ul class=\"fig-list\">\n<li>Weiterleitung zum Merge-Knoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zweig [FALSE] – Bypass:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wenn ein anderer Data-ID-Modus konfiguriert ist, wird kein Nibble aus den Nutzdaten gelesen.</li>\n<li>Direkter Sprung auf den Merge-Knoten.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschluss:</strong> Zusammenführung im <em>Merge Node</em> und Übergang zum nachfolgenden Schritt der Prüflogik (Validierung des CRC bzw. Vergleich des DataIDNibbles mit der erwarteten Data-ID).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Zuordnung:</strong> Erfüllt die Anforderungen [PRS_E2E_00582] (Verhalten des Leseschritts) und [PRS_E2E_00517] i. V. m. [RS_E2E_08539].</li>\n<li><strong>Bit-Alignment & Endianness:</strong></li>\n<li>Der Bit-Offset (<code>NibbleOffset</code>) bezieht sich strikt auf Little-Endian-Bit-Nummerierung (Bit 0 = niederwertigstes Bit im Byte).</li>\n<li><code>NibbleOffset</code> muss zwingend auf eine Nibble-Grenze ausgerichtet sein (Bit-Position modulo 4 == 0). Ein Nibble darf gemäß Spezifikation nicht über Byte-Grenzen hinweg fragmentiert werden.</li>\n<li><strong>Implementierungsfalle im Spezifikations-Kommentar:</strong></li>\n<li>Der Text der informativen Note im Diagramm verwendet irrtümlich den Variablennamen <code>Counter = ...</code> (Textübertrag aus dem Zähler-Extraktionsschritt). Für die Implementierung ist dieser Wert semantisch exakt als <code>ReceivedNibble</code> zu führen.</li>\n<li><strong>Effizienz / Optimierung:</strong></li>\n<li>Da <code>NibbleOffset &amp; 0x7</code> entweder <code>0</code> (unteres Nibble) oder <code>4</code> (oberes Nibble) ergibt, lässt sich der Shift-Ausdruck auf 8-Bit-Microcontrollern compilerseitig oder per Makro auf eine einfache Verzweigung oder Fest-Shift-Operation optimieren:</li>\n<li>Offset im Byte = 0: <code>Data[...] &amp; 0x0F</code></li>\n<li>Offset im Byte = 4: <code>(Data[...] &gt;&gt; 4) &amp; 0x0F</code></li>\n<li><strong>Defensive Robustheit:</strong> <code>Data</code> muss vor Betreten dieses Schritts validiert sein (<code>Data != NULL</code> und PDU-Länge deckt <code>(NibbleOffset + 4)</code> ab), um Out-of-Bounds-Lesezugriffe zu verhindern.</li>\n</ul>"}], "trans": [{"from": "FIG-b296fe80ae396e5c", "to": "FIG-094a54c7051d0605", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Entfernung von Bildartefakten am oberen Bildrand (abgeschnittene Textfragmente „... behave as shown in Figure 6.108...“ und Umrandung des Funktionssymbols E2E_P11Check()).</li>\n<li>Bereinigung eines Artefakts (Text-/Linienfragment) bei Koordinate (402, 162) links neben der Aktionsbox.</li>\n</ul>"}, {"from": "FIG-094a54c7051d0605", "to": "FIG-3395dac47b8835d5", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
